pseudocode:
1. split logs into letterLogs and digitLogs
2. letterLogs.sort((a, b) => {
3.   let valA = a.substring(a.indexOf(' ') + 1);
4.   let valB = b.substring(b.indexOf(' ') + 1);
5.   if (valA !== valB) return valA.localeCompare(valB);
6.   return a.split(' ')[0].localeCompare(b.split(' ')[0]);
7. });
8. return [...letterLogs, ...digitLogs];
